/** Real framework sessions and native RemoteViews, using generated artwork only. */
public final class CreativeSmoke {
    private final Instrumentation i;private final Context c;private final AppWidgetHost host;private final BiConsumer<Boolean,String> check;
    private MediaSession session;private VolumeProvider volume;private Bitmap art;private int id=-1;private final AtomicInteger taps=new AtomicInteger();
    private CreativeSmoke(Instrumentation i,Context c,AppWidgetHost host,BiConsumer<Boolean,String> check){this.i=i;this.c=c;this.host=host;this.check=check;}
    public static void run(Instrumentation i,Context c,AppWidgetHost host,BiConsumer<Boolean,String> check)throws Exception{new CreativeSmoke(i,c,host,check).run();}
    private void main(Runnable task){AtomicReference<Throwable> error=new AtomicReference<>();i.runOnMainSync(()->{try{task.run();}catch(Throwable t){error.set(t);}});if(error.get()!=null)throw new AssertionError(error.get());i.waitForIdleSync();}
    private void shell(String cmd)throws Exception{try(ParcelFileDescriptor fd=i.getUiAutomation().executeShellCommand(cmd);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd)){in.readAllBytes();}}
    private void await(BooleanSupplier condition,String message)throws Exception{long end=SystemClock.elapsedRealtime()+7000;while(!condition.getAsBoolean()&&SystemClock.elapsedRealtime()<end)Thread.sleep(60);check.accept(condition.getAsBoolean(),message);}
    private View render(String kind,JSONObject config,int width,int height){try{config.put("_width",width).put("_height",height);}catch(Exception e){throw new RuntimeException(e);}View v=Widgets.render(c,id,kind,config,false,false).apply(c,new FrameLayout(c));v.measure(View.MeasureSpec.makeMeasureSpec(Ui.dp(c,width),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(Ui.dp(c,height),View.MeasureSpec.EXACTLY));v.layout(0,0,v.getMeasuredWidth(),v.getMeasuredHeight());return v;}
    private void fits(View root,int target){View v=root.findViewById(target);Rect r=new Rect();v.getDrawingRect(r);((ViewGroup)root).offsetDescendantRectToMyCoords(v,r);check.accept(v.getWidth()>0&&v.getHeight()>0&&r.left>=0&&r.right<=root.getWidth()&&r.top>=0&&r.bottom<=root.getHeight(),"Creative controls stay inside the allocated widget");}
    private void playback(long actions){session.setPlaybackState(new PlaybackState.Builder().setState(PlaybackState.STATE_PAUSED,43000,0).setActions(actions).build());}
    private JSONObject config(int variant){JSONObject cfg=Widgets.defaults("music");ExtraData.put(cfg,"variant",variant);return cfg;}
    private boolean bubbleLit(View view){ImageView image=view.findViewById(com.nook.widgets.R.id.music_scene);if(image==null||!(image.getDrawable() instanceof BitmapDrawable draw))return false;Bitmap b=draw.getBitmap();int color=b.getPixel(b.getWidth()*3/4,Math.round(b.getHeight()*.435f));return Color.green(color)>Color.red(color)*1.2f;}
    private void board(){main(()->{try{
        Bitmap sheet=Bitmap.createBitmap(1600,1560,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(sheet);canvas.drawColor(0xff141c1c);Paint p=new Paint(3);p.setColor(0xfff0f2e9);p.setTextSize(32);canvas.drawText("Nook · a different way to play",30,48,p);
        for(int n=0;n<9;n++){int x=26+n%3*526,y=90+n/3*480;JSONObject cfg;String kind,name;if(n<7){cfg=config(n+4);kind="music";name=CreativeMusic.NAMES[n];}else{kind="buds";cfg=Widgets.defaults(kind);cfg.put("variant",n==7?0:1).put("style",n==7?0:3).put("budsManual",true).put("budsName","Sample earbuds").put("budsBattery",78).put("budsLeft",82).put("budsRight",74).put("budsCase",61).put("budsManualAt",System.currentTimeMillis());name=n==7?"Buds · Dark Stage":"Buds · Glass Gauge";}
            View v=render(kind,cfg,320,250);FrameLayout frame=new FrameLayout(c);if(n==8)frame.setBackgroundResource(com.nook.widgets.R.drawable.preview_wallpaper);frame.addView(v,new FrameLayout.LayoutParams(-1,-1));frame.measure(View.MeasureSpec.makeMeasureSpec(Ui.dp(c,320),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(Ui.dp(c,250),View.MeasureSpec.EXACTLY));frame.layout(0,0,frame.getMeasuredWidth(),frame.getMeasuredHeight());p.setTextSize(22);canvas.drawText(name,x,y,p);canvas.save();canvas.translate(x,y+20);canvas.scale(500f/frame.getWidth(),390f/frame.getHeight());frame.draw(canvas);canvas.restore();}
        p.setTextSize(20);canvas.drawText("Native widget renders · generated media artwork · manually entered sample buds batteries",26,1540,p);File folder=new File(c.getFilesDir(),"screenshots");folder.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(folder,"creative-players-buds.png"))){sheet.compress(Bitmap.CompressFormat.PNG,100,out);}sheet.recycle();
    }catch(Exception e){throw new RuntimeException(e);}});}
    private void run()throws Exception{
        String address="00:11:22:33:44:55";android.content.SharedPreferences reports=c.getSharedPreferences("buds_reports",0);
        try{
            shell("cmd notification allow_listener com.nook.widgets/com.nook.widgets.MediaListener");await(()->MediaAccess.allowed(c),"Creative players can discover sessions");
            main(()->{art=Bitmap.createBitmap(320,320,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(art);Paint p=new Paint(3);p.setShader(new LinearGradient(0,0,320,320,new int[]{0xff123744,0xffe2735a,0xffefc97e},null,Shader.TileMode.CLAMP));canvas.drawRect(0,0,320,320,p);p.setShader(null);p.setColor(0xffffdd9b);canvas.drawCircle(210,95,54,p);p.setColor(0xff193b46);for(int n=0;n<8;n++)canvas.drawRect(n*45,220+n%3*20,n*45+30,320,p);session=new MediaSession(c,"Creative generated fixture");session.setCallback(new MediaSession.Callback(){public void onPlay(){taps.incrementAndGet();}public void onPause(){taps.incrementAndGet();}public void onSkipToNext(){taps.incrementAndGet();}public void onSkipToPrevious(){taps.incrementAndGet();}},new Handler(Looper.getMainLooper()));session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,"Sunroom Signals").putString(MediaMetadata.METADATA_KEY_ARTIST,"Paper Satellites").putLong(MediaMetadata.METADATA_KEY_DURATION,210000).putBitmap(MediaMetadata.METADATA_KEY_ALBUM_ART,art).build());playback(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS);volume=new VolumeProvider(VolumeProvider.VOLUME_CONTROL_ABSOLUTE,10,4){};session.setPlaybackToRemote(volume);session.setActive(true);});await(()->MediaAccess.controller(c)!=null,"Generated creative session is active");
            id=host.allocateAppWidgetId();check.accept(AppWidgetManager.getInstance(c).bindAppWidgetIdIfAllowed(id,new ComponentName(c,Widgets.Music.class)),"Creative music binds to Android's widget host");
            for(int variant=4;variant<11;variant++){final int style=variant;
                for(int surface=0;surface<4;surface++){final int material=surface;main(()->{for(int[] size:new int[][]{{320,250},{320,182},{180,120},{320,100}})try{JSONObject cfg=config(style).put("style",material);View v=render("music",cfg,size[0],size[1]);check.accept(((TextView)v.findViewById(com.nook.widgets.R.id.widget_title)).getText().toString().equals("Sunroom Signals"),"Every creative style retains actual track metadata");for(int target:new int[]{com.nook.widgets.R.id.widget_action0,com.nook.widgets.R.id.widget_action1,com.nook.widgets.R.id.widget_action2})fits(v,target);View scene=v.findViewById(com.nook.widgets.R.id.music_scene);if(size[0]>=240&&size[1]>=165)check.accept(scene!=null&&((ImageView)scene).getDrawable()!=null,"Creative object is drawn in spacious widgets");}catch(Exception e){throw new RuntimeException(e);}});}
                for(int font=0;font<6;font++){int f=font;main(()->{JSONObject cfg=config(style);ExtraData.put(cfg,"font",f);render("music",cfg,320,250);check.accept(true,"Creative font resource inflates");});}
                JSONObject cfg=config(style);Store.config(c,id,cfg);AtomicReference<View> rendered=new AtomicReference<>();main(()->rendered.set(render("music",cfg,320,250)));for(int target:new int[]{com.nook.widgets.R.id.widget_action0,com.nook.widgets.R.id.widget_action1,com.nook.widgets.R.id.widget_action2}){int before=taps.get();main(()->rendered.get().findViewById(target).performClick());await(()->taps.get()==before+1,"Each creative transport reaches its real MediaSession");}
                main(()->{JSONObject hidden=config(style);ExtraData.put(hidden,"musicHideText",true);View v=render("music",hidden,320,250);check.accept(v.findViewById(com.nook.widgets.R.id.music_copy).getVisibility()==View.GONE&&v.findViewById(com.nook.widgets.R.id.music_timeline).getVisibility()==View.GONE,"Creative hidden-text mode removes metadata and timeline");});
            }
            JSONObject bubbles=config(7);Store.config(c,id,bubbles);AtomicReference<AppWidgetHostView> bubbleHost=new AtomicReference<>();main(()->{host.startListening();Widgets.update(c,id,"music");bubbleHost.set(host.createView(c,id,AppWidgetManager.getInstance(c).getAppWidgetInfo(id)));});Thread.sleep(400);check.accept(!bubbleLit(bubbleHost.get()),"A quieter reported output leaves the sixth bubble dark");main(()->volume.setCurrentVolume(7));await(()->bubbleLit(bubbleHost.get()),"Volume-only session callbacks redraw Bubble Lab in the real widget host");
            board();
            main(()->{playback(PlaybackState.ACTION_PLAY);View v=render("music",config(4),320,250);check.accept(!v.findViewById(com.nook.widgets.R.id.widget_action0).isEnabled()&&!v.findViewById(com.nook.widgets.R.id.widget_action2).isEnabled(),"Creative styles disable unsupported transport");});
            for(int variant=0;variant<3;variant++)for(int design=0;design<8;design++){int v=variant,d=design;main(()->{for(int[] size:new int[][]{{320,250},{320,182},{180,130}})try{JSONObject cfg=Widgets.defaults("buds");WidgetDesign.select(cfg,d);cfg.put("variant",v);View view=render("buds",cfg,size[0],size[1]);fits(view,com.nook.widgets.R.id.widget_settings);check.accept(((ImageView)view.findViewById(com.nook.widgets.R.id.buds_scene)).getDrawable()!=null,"Buds artwork inflates across design languages");}catch(Exception e){throw new RuntimeException(e);}});}
            JSONObject cfg=Widgets.defaults("buds").put("budsAddress",address);reports.edit().putInt(address+".battery",78).putLong(address+".at",System.currentTimeMillis()).commit();Context deniedContext=new ContextWrapper(c){@Override public int checkSelfPermission(String permission){return permission.equals("android.permission.BLUETOOTH_CONNECT")?android.content.pm.PackageManager.PERMISSION_DENIED:super.checkSelfPermission(permission);}};BudsData.State denied=BudsData.read(deniedContext,cfg);check.accept(denied.battery==-1&&!denied.online&&denied.status.equals("Allow Nearby devices"),"Denied Bluetooth permission never exposes a cached system reading or connection");
            cfg.put("budsManual",true).put("budsLeft",80).put("budsRight",64).put("budsCase",101).put("budsBattery",70).put("budsManualAt",System.currentTimeMillis());BudsData.State manual=BudsData.read(c,cfg);check.accept(manual.manual&&manual.left==80&&manual.right==64&&manual.caseLevel==-1&&manual.source.equals("Manual readings"),"Manual per-piece readings are labeled and validated even without Bluetooth access");cfg.put("budsManualAt",System.currentTimeMillis()-25*60*60*1000L);check.accept(BudsData.read(c,cfg).source.contains("older than 24h"),"Old manual readings are visibly marked");
            shell("pm grant com.nook.widgets android.permission.BLUETOOTH_CONNECT");cfg.put("budsManual",false);BudsData.State reported=BudsData.read(c,cfg);check.accept(reported.battery==78&&reported.left==-1&&reported.right==-1&&reported.caseLevel==-1&&reported.source.startsWith("Last reported"),"Combined reports never invent left, right or case values");reports.edit().putLong(address+".at",System.currentTimeMillis()-25*60*60*1000L).commit();check.accept(BudsData.read(c,cfg).battery==-1,"Expired system battery readings become unavailable");check.accept(c.getPackageManager().getReceiverInfo(new ComponentName(c,BudsReceiver.class),0).permission.equals("android.permission.BLUETOOTH_PRIVILEGED"),"Only privileged Bluetooth senders can supply battery broadcasts");
            int budsId=host.allocateAppWidgetId();try{check.accept(AppWidgetManager.getInstance(c).bindAppWidgetIdIfAllowed(budsId,new ComponentName(c,Widgets.Buds.class)),"Dedicated buds provider binds");}finally{host.deleteAppWidgetId(budsId);}
            main(()->{try{JSONObject hub=Widgets.defaults("universal").put("page","buds");View v=render("universal",hub,320,340);check.accept(v.findViewById(com.nook.widgets.R.id.buds_scene)!=null,"Buds can switch into the Universal widget");}catch(Exception e){throw new RuntimeException(e);}});
        }finally{reports.edit().remove(address+".battery").remove(address+".at").commit();main(host::stopListening);if(session!=null)main(session::release);if(art!=null)art.recycle();if(id>0){host.deleteAppWidgetId(id);Store.removeConfig(c,id);}shell("cmd notification disallow_listener com.nook.widgets/com.nook.widgets.MediaListener");}
    }
}
